async function remember(e){if(!uid()||completed(e))return;if(!W.ForumAPITicket)throw Error('\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435');const record={key:stamp(e),rule:e.rule,day:day(serverNow),time:serverNow};await store({method:'storage.set',user_id:uid(),key:VISITS,token:W.ForumAPITicket,action:'append',value:'\n'+JSON.stringify(record)});visits.push(record);}
